<?php

namespace App\Core\Registration;

use App\Core\Models\Company;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * Public registration funnel event. ADR-849 (M10) : one row per (funnel_id, step) ; `funnel_id` is a random journey id
 * generated by the browser (sessionStorage), never a personal datum. `completed` is written by the server only
 * (RegisterCompanyUseCase) ; Platform-created companies never write here.
 */
class RegistrationFunnelEvent extends Model
{
    /** steps the public registration screen really goes through (resources/js/pages/register/index.vue) */
    public const CLIENT_STEPS = ['started', 'industry', 'plan', 'addons', 'company', 'account'];

    public const COMPLETED = 'completed';

    protected $fillable = ['session_id', 'funnel_id', 'company_id', 'step', 'metadata'];

    protected $casts = [
        'metadata' => 'array',
    ];

    // ── Relations ────────────────────────────────────────

    public function company(): BelongsTo
    {
        return $this->belongsTo(Company::class);
    }

    // ── Scopes ───────────────────────────────────────────

    public function scopeStep(Builder $query, string $step): Builder
    {
        return $query->where('step', $step);
    }

    public function scopeInPeriod(Builder $query, $from, $to): Builder
    {
        return $query->whereBetween('created_at', [$from, $to]);
    }
}
